/// Rough token estimate for a string — DELEGATED to `llm::estimate_tokens`, deliberately.
///
/// This used to be its own `s.len() / 4 + 1`, and `crates/llm` had already replaced that with a
/// MEASURED 3.8 chars/token (this repo's `CLAUDE.md` is 94,357 chars and Ollama reported 24,604
/// tokens for it). The agent never adopted it, so ONE budget calculation ran on TWO estimators and
/// the compacting was done by the wrong one. `/4` under-counts by ~4%, and as that crate's doc says,
/// under-counting "is the direction that hurts: it is what lets the budget math conclude 'fits' for a
/// prompt that does not, and an overflow costs half the window rather than the excess".
pub(crate) fn estimate_tokens(s: &str) -> usize {
    llm::estimate_tokens(s)
}
